//
// Arquiteturas de Alto Desempenho 2026/2027 --- assignment A1
//
// ISPC engine (C side), see sha1_ispc.ispc
//
// the ISPC object file is compiled for one target (makefile: ISPC_TARGET, for example avx2-i32x8);
// its number of lanes (programCount) is obtained at run time with sha1_ispc_lanes()
//
// requires: sha1_simd.h (lanes_t) and the result_t / CHECK_PERIOD / now() / search_stopped()
// definitions of sha1_engines.h
//

#ifndef SHA1_ISPC
#define SHA1_ISPC

#include "sha1_ispc_ispc.h" // generated by ispc -h

#ifndef ISPC_LANES
# define ISPC_LANES  8 // programCount of the target (only used for the CSV file, checked at run time)
#endif

static int ispc_setup(search_t *s,lanes_t *L)
{
  int n = (int)sha1_ispc_lanes();

  if(n != ISPC_LANES || n > MAX_LANES)
  {
    fprintf(stderr,"ispc: the object file has %d lanes, expected %d (fix ISPC_LANES in the makefile)\n",n,ISPC_LANES);
    exit(1);
  }
  if(lanes_init(s,L,n) != 0)
    exit(1);
  return n;
}

static void run_ispc(search_t *s,double max_seconds,int bench,u32_t mask,result_t *res)
{
  lanes_t L;
  int n = ispc_setup(s,&L);
  double t0 = now();

  for(;;)
  {
    for(u32_t it = 0u;it < CHECK_PERIOD / (u32_t)n;it++)
    {
      int64_t found = sha1_ispc_step(s->state,s->w,&L.delta[0][0],s->n_chunks,L.wfirst,L.wlast,mask,NULL);

      res->attempts += (uint64_t)n;
      if(found != 0)
        for(int j = 0;j < n;j++)
          if((found >> j) & 1)
          { // lane j has a solution
            res->n_found++;
            if(!bench)
            {
              lanes_apply(s,&L,j);
              res->found = 1;
              res->seconds = now() - t0;
              return;
            }
          }
      if(!search_next(s))
      {
        res->exhausted = 1;
        res->seconds = now() - t0;
        return;
      }
    }
    if((res->seconds = now() - t0) >= max_seconds || search_stopped())
      return;
  }
}

static int test_ispc(search_t *s,file_template_t *t,int n_tests)
{
  lanes_t L;
  int n = ispc_setup(s,&L);
  u32_t hash[5 * MAX_LANES],h[5],g[5];

  for(int k = 0;k < n_tests;k++)
  {
    int64_t found = sha1_ispc_step(s->state,s->w,&L.delta[0][0],s->n_chunks,L.wfirst,L.wlast,0xFu,hash); // weak mask: about 1 lane in 16 succeeds

    for(int j = 0;j < n;j++)
    {
      lanes_apply(s,&L,j);
      search_hash(s,h);             // scalar engine, same counter
      search_store(s,t);
      sha1_buffer(t->data,t->size,g); // SHA1 of the whole file
      for(int i = 0;i < 5;i++)
        if(hash[i * n + j] != h[i] || h[i] != g[i])
        {
          fprintf(stderr,"test_ispc: mismatch (test %d, lane %d, word %d)\n",k,j,i);
          return -1;
        }
      if((int)((found >> j) & 1) != ((h[4] & 0xFu) == 0u))
      {
        fprintf(stderr,"test_ispc: wrong found mask (test %d, lane %d)\n",k,j);
        return -1;
      }
    }
    lanes_apply(s,&L,0);
    for(int r = 1 + (k * 7919) % 1000;r > 0;r--) // jump ahead, exercising the carries
      (void)search_next(s);
  }
  printf("test_ispc: %d tests x %d lanes passed\n",n_tests,n);
  return 0;
}

#endif
